          next: [{ to: "deliver", when: "at(pov, 'far_bank_waystation') and carries(pov, 'wren_satchel')" }],
          objectives: [{ label: "Cross the river by The Wend ferry", when: "at(pov, 'far_bank_waystation')" }],
          gate: "flag('ferry_running')",
          fail: { when: "clock >= 6120 and not carries('bram_hesketh', 'fever_poultice')", to: "too_late" },
          hints: ["If the ferry is shut, Tamsin will say when the water is fit to cross.", "A storm closes the ferry for most of a day; plan around it."]
