    "calendar.school": {
      id: "calendar.school",
      pack: "calendar",
      schema: "lre-table/calendar.school/v1",
      revision: "8f8b2a866c57b80725af82648a9d868c",
      label: "School year",
      source: {
        dataPack: "modern-us",
        file: "us/calendar.json",
        sourceSchema: "lre-data-src/us/calendar/v1",
        reflectsPeriod: "2025-2026 rules (no dated instances; rules are stable across years)",
        approximate: true,
        basis: "US Code 5 USC 6103 (federal holidays), NIST/US DOT daylight-saving rules (Uniform Time Act as amended 2005), typical K-12 and college academic calendars from state/district and university catalogs as recalled, BLS National Compensation Survey for paid-holiday prevalence, FLSA and FMCSA hours rules."
      },
      columns: { title: { type: "text" }, values: { type: "json", doc: "The school-year section as in the source: windows, daily hours, breaks, terms." } },
      rows: {
        k12: {
          title: "K-12",
          values: {
            instructional_days: { typical: 180, min_by_state: 160, max_by_state: 186, note: "Most states require 175-180 days; some set hours instead of days." },
            start_window_by_region: {
              "South and Southwest": "Aug 4-Aug 15",
              West: "Aug 10-Sep 1",
              Midwest: "Aug 15-Sep 3",
              Northeast: "Aug 28-Sep 8 (after Labor Day in NY/NJ/New England)"
            },
            end_window_by_region: { "South and Southwest": "May 16-May 30", West: "Jun 1-Jun 12", Midwest: "May 24-Jun 8", Northeast: "Jun 10-Jun 25" },
            typical_school_day: { elementary: "08:30-15:15", middle: "08:00-15:10", high: "07:30-14:45", instructional_hours_per_day_approx: 6.5 },
            breaks: [
              { id: "labor_day", name: "Labor Day", when: "first Monday of September", length_days: 1 },
              { id: "fall_break", name: "Fall or October break (some districts)", when: "mid-October, varies", length_days: "1-5" },
              {
                id: "thanksgiving",
                name: "Thanksgiving break",
                when: "Wednesday before Thanksgiving through the Friday after (a full week in some Southern districts)",
                length_days: "3-5"
              },
              { id: "winter_break", name: "Winter break", when: "around Dec 20 through Jan 2", length_days: "10-16" },
              { id: "mlk_day", name: "Martin Luther King Jr. Day", when: "third Monday of January", length_days: 1 },
              {
                id: "presidents_week",
                name: "Presidents' Day or mid-winter break",
                when: "third Monday of February; a full week in the Northeast",
                length_days: "1-5"
              },
              {
                id: "spring_break",
                name: "Spring break",
                when: "one week between early March and mid-April (often near Easter)",
                length_days: "5-9"
              },
              { id: "memorial_day", name: "Memorial Day", when: "last Monday of May", length_days: 1 }
            ],
            summer_break_weeks_approx: 10,
            note: "School year start/end shown as windows; the engine should pick a consistent date per region."
          }
        },
        college: {
          title: "College",
          values: {
            semester_system: {
              fall: {
                classes_begin_window: "Aug 18-Sep 3",
                thanksgiving_break: "Wed-Sun of Thanksgiving week",
                classes_end_window: "Dec 5-Dec 12",
                finals_window: "Dec 8-Dec 20",
                instructional_weeks: 15
              },
              winter_break_weeks: "4-5 (about Dec 20-Jan 15)",
              spring: {
                classes_begin_window: "Jan 12-Jan 25 (often the week of MLK Day)",
                spring_break: "one week, March 8-March 25",
                classes_end_window: "Apr 28-May 10",
                finals_window: "May 5-May 15",
                commencement_window: "May 8-May 25",
                instructional_weeks: 15
              },
              summer_sessions: { window: "May 20-Aug 15", note: "Shorter 4-6 week terms; fewer students." }
            },
            quarter_system: {
              fall: "late Sep-mid Dec",
              winter: "early Jan-mid Mar",
              spring: "late Mar-early Jun",
              summer: "optional, Jun-Aug",
              instructional_weeks_per_term: 10,
              note: "Used by a minority of colleges (e.g. several UC and Pacific Northwest schools)."
            },
            typical_course_load: { full_time_credits_per_term: "12-15", weekly_class_hours: "12-16", study_hours_per_week_approx: "20-30" }
          }
        }
      }
    },
