// src/migrate/worlds.ts
var WORLD_FILE = /^worlds\/([^/]+)\/(index\.json|draft\.json|history\.json|rev\/[0-9a-f]{32}\.json)$/;
async function carryWorlds(db, user, folder, items, run) {
  const files = [];
  for (const item2 of items) {
    const match = item2.where === "user storage" && item2.row === "worlds" && item2.fate === "carried" ? WORLD_FILE.exec(item2.path) : null;
    if (!match || folder === null)
      continue;
    const bytes = await readBytes(join8(folder, item2.path));
    if (bytes !== null)
      files.push({ world: match[1] ?? "", file: match[2] ?? "", bytes });
  }
  db.transaction(() => {
    db.run("DELETE FROM world_file WHERE user = ?", [user]);
    const put2 = db.query("INSERT INTO world_file (user, world, file, bytes, sha256, run) VALUES (?, ?, ?, ?, ?, ?)");
    for (const f of files)
      put2.run(user, f.world, f.file, f.bytes, sha256(f.bytes), run);
  })();
  const count = (name) => files.filter((f) => f.file === name).length;
  return { worlds: count("index.json"), revisions: files.filter((f) => f.file.startsWith("rev/")).length, drafts: count("draft.json"), histories: count("history.json"), bytes: files.reduce((n, f) => n + f.bytes.length, 0) };
}

// src/migrate/carry.ts
var IMPORTED2 = {
  "chat-run": "RPE's store: each chat with the world and revision it plays",
  ledger: "RPE's store: a turn tied to its message for every reply and swipe, its changes what today's fold applied there; each swipe's record as today's build kept it in the migration's imported_record, beside its turn, read-only",
  "pack-state": "RPE's store: the changes of each turn, folded by the same packs' handlers",
  "secret-holdings": "RPE's store: the knowledge events among each turn's changes, folded into the minds state as today",
  "chat-places": "RPE's store: the chat's own place and map events among each turn's changes",
  "story-record": "RPE's story record and cast, each on the turn whose record held it; each swipe's record also kept word for word beside its turn in the migration's imported_record, read-only",
  unplayed: "Inside each swipe's record, kept word for word beside its turn in the migration's imported_record, read-only",
  departures: "Inside each swipe's record, kept word for word beside its turn in the migration's imported_record, read-only"
};
async function placesOf3(today6, items, tree) {
  const runtime = today6.runtime.runtimes[0]?.name ?? null;
  const trouble = runtime === null ? null : await bookTrouble(runtime, today6.runtime.files);
  return (item2) => {
    if (item2.row === "connections")
      return trouble === null ? "lands" : { none: `the runtime ${runtime}: ${trouble}` };
    if ((item2.row === "learned-and-home" || item2.row === "author-notes" || item2.row === "texts") && !tree)
      return { none: "this run was not given the file tree's places" };
    return item2.row !== null && Object.hasOwn(NO_PLACE_YET, item2.row) ? "later" : "lands";
  };
}
async function carry(input) {
  const { today: today6, report, paths, db, store, s, run, now, tree } = input;
  const user = today6.sources.userId;
  const worlds = await carryWorlds(db, user, today6.user, report.items, run);
  const earlier = putPrints(db, user);
  const runtime = today6.runtime.runtimes[0]?.name ?? null;
  const serial = oneToolAtATime(await lumiahSettings(today6));
  const carriedConnections = runtime === null ? null : await carryConnections(modelsPort(paths, new SecretsFile(paths.secrets)), runtime, today6.runtime.files, serial, earlier);
  const connections = carriedConnections === null || "why" in carriedConnections ? carriedConnections : carriedConnections.carried;
  if (carriedConnections !== null && !("why" in carriedConnections))
    keepPutPrints(db, user, carriedConnections.put);
  const carriedSettings = await carrySettings(today6, report.items, paths.globalConfig, earlier);
  keepPutPrints(db, user, carriedSettings.put);
  const settings = carriedSettings.carried;
  const chats = (report.imports ?? []).filter((c) => c.outcome === "imported" || c.outcome === "replaced").map((c) => c.chatId);
  const turnAreas = new TurnAreas(today6, db, s, report.items);
  const ownFiles = tree === null ? null : await carryOwnFiles(today6, report.items, tree, { db, s, areas: turnAreas, carried: new Set(chats) });
  db.transaction(() => {
    dropLeftoverStory(store, s.id);
    dropLeftoverCast(store, s.id);
  })();
  const people = new People(db, store, s, now);
  const fate = (chat) => {
    const c = report.imports?.find((i) => i.chatId === chat);
    const why2 = c !== undefined ? `${c.outcome}${c.why ? `: ${c.why}` : ""}` : today6.chats.some((row) => row.id === chat) ? "not read: today's build plays no world in it" : "gone from Lumiverse";
    return { why: why2, kept: s.chat(chat) !== null };
  };
  const minds = await carryMinds({ db, s, chats, areas: turnAreas, people, now, fate });
  const story = db.transaction(() => carryStory({ db, store, s, chats, people, now, inside: new Map(report.chats.map((c) => [c.chatId, c.story])), fate }))();
  const [mindsFound, storyFound] = ["mind-files", "story-record"].map((row) => report.rows.find((r) => r.row === row)?.inside?.count ?? 0);
  const files = new Set(minds.characters.flatMap((c) => c.files.map((f) => `${c.character}\x00${f}`))).size;
  const characters = new Set(minds.characters.map((c) => c.character)).size;
  const landed = {
    ...IMPORTED2,
    worlds: `RPE's database (world_file): ${worlds.worlds} world(s) with ${worlds.revisions} revision(s), ${worlds.drafts} draft(s) and ${worlds.histories} history file(s), byte for byte, each with its checksum`,
    "world-contents": "Inside the world documents, as they were: RPE reads them with today's world store, so each world holds what it held",
    pins: "Inside the world documents they pin, carried with them",
    settings: `RPE-global.yml: ${settings.carried.length} setting(s) carried; ${(settings.notCarried ?? []).length > 0 ? `${(settings.notCarried ?? []).length} not carried, as RPE's like setting means something else or takes no such value; ` : ""}${settings.noHome.length} with no setting of the same meaning in RPE yet, listed by name`,
    "model-choices": `Listed for you: ${settings.lumiverseConnections.length} setting(s) name a connection that lives in Lumiverse, which RPE can't use; that work uses RPE's default connection until you pick one of RPE's`,
    "runtime-settings": "Listed by name with your settings: RPE's config has no setting for the runtime's tuning or memory limit yet; its update choice is RPE's update.restart, carried with them",
    loopback: "At the swap (rpe up): the hash of its key among RPE's provider keys, RPE answering at today's address under today's model name; the connection in Lumiverse is left as it is",
    "mind-files": [
      `On each character's record in the cast, word for word, per turn, marked imported and not yet filed (the cast's mind part): ${minds.versions} version(s) of ${files} file(s) of ${characters} character(s), ${minds.versions - minds.unlisted} of the ${mindsFound} found in today's areas${minds.unlisted > 0 ? ` and ${minds.unlisted} read from the area a turn's record names, which no area document of its chat holds` : ""}`,
      ...minds.untied > 0 ? [`${minds.untied} version(s) in areas no imported turn ended with (before any turn, a generation that left no reply, or a reply's that a Continue then changed) are in the backup only`] : [],
      ...minds.shared > 0 ? [`${minds.shared} version(s) in a branch's own areas, the same as the chat it was made from holds, are on the records of the turns the two share`] : [],
      ...minds.gone > 0 ? [`${minds.gone} version(s) whose text today's clean-up had removed are listed as not read`] : [],
      ...apartText(minds.apart, "version(s)")
    ].join("; "),
    "story-record": [
      `${IMPORTED2["story-record"]}: ${story.beats} beat(s), ${story.struck} struck, ${story.futures} draft(s) as proposed futures, ${story.castings} casting(s) in the cast${story.pinned > 0 ? `, ${story.pinned} pinned as the player pinned them` : ""}, ${story.beats + story.struck + story.futures + story.castings} of the ${storyFound} entr(ies) found in today's records`,
      ...story.leftOut > 0 ? [`${story.leftOut} damaged entr(ies) today's reader leaves out are in imported_record only`] : [],
      ...story.shared > 0 ? [`${story.shared} entr(ies) in the records a branch copied from the chat it was made from are carried once, with the turns the two share`] : [],
      ...story.unheld > 0 ? [`${story.unheld} entr(ies) on records no imported turn holds are in the backup only`] : [],
      ...apartText(story.apart, "entr(ies)")
    ].join("; ")
  };
  if (connections !== null && !("why" in connections))
    landed.connections = `RPH's two documents, through the models port: ${connections.connections.length} connection(s) in RPE-global.yml's models; ${connections.keys} key(s), ${connections.signins} sign-in(s) and ${connections.headerValues} header value(s) in the secrets file and nowhere else`;
  if (tree !== null && ownFiles !== null) {
    const at3 = `The user's level of the file tree, under ${IMPORTED}/, switched off`;
    const inChat = `that chat's own notes folder, under ${tree.notes}/${IMPORTED}/, which no other chat's agents read`;
    const alone = `${ownFiles.leftAlone > 0 ? `; ${ownFiles.leftAlone} chat(s) played on RPE keep the notes they have` : ""}${ownFiles.kept > 0 ? `; ${ownFiles.kept} chat(s) this run did not import keep the notes an earlier run wrote` : ""}`;
    landed["own-agents"] = `${at3}: ${ownFiles.agents} agent(s) in ${tree.agents}/ and ${ownFiles.skills} skill(s) in ${tree.skills}/, each in the new header format with the original beside it`;
    landed.texts = `${at3}: ${ownFiles.texts} edited text(s) in ${tree.prompts}/, each named for what it was; ${ownFiles.promptSets} prompt set(s) today's turns recorded, word for word, in ${PROMPT_SETS}/, each named by the hash the turns' records give it`;
    landed.guidance = `${at3}: GUIDANCE.md (${ownFiles.guidance})`;
    landed["author-notes"] = `Each chat's area as the reply it shows left it, in ${inChat} (${ownFiles.notes} file(s)); every version before it, by the turn that wrote it, under ${VERSIONS}/ there (${ownFiles.versions} file(s)), with beside each the notes that turn removed or moved away (${ownFiles.removals})${alone}`;
    landed["learned-and-home"] = `${at3}: your ~/ files in home/ (${ownFiles.home} file(s)); each chat's learned/ in ${inChat}, as learned/ (${ownFiles.learned} file(s))${alone}`;
  }
  return { landed, carried: { worlds, settings, connections, ownFiles, minds, story } };
}

