// src/app/main.ts
async function secret(question) {
  if (!process.stdin.isTTY) {
    const first = (await Bun.stdin.text()).split(/\r?\n/)[0]?.trim() ?? "";
    return first === "" ? null : first;
  }
  process.stderr.write(question);
  const stdin = process.stdin;
  const answered = Promise.withResolvers();
  let typed = "";
  const onData = (chunk) => {
    for (const ch of chunk) {
      const done = ch === "\r" || ch === `
` ? typed : ch === "\x03" || ch === "\x04" ? null : undefined;
      if (done !== undefined) {
        stdin.off("data", onData);
        stdin.setRawMode(false);
        stdin.pause();
        process.stderr.write(`
`);
        answered.resolve(done === "" ? null : done);
        return;
      }
      typed = ch === "\x7F" || ch === "\b" ? typed.slice(0, -1) : typed + ch;
    }
  };
  stdin.setRawMode(true);
  stdin.setEncoding("utf8");
  stdin.on("data", onData);
  stdin.resume();
  return await answered.promise;
}
function stopped() {
  const stop3 = Promise.withResolvers();
  for (const signal2 of ["SIGINT", "SIGTERM"])
    process.once(signal2, () => stop3.resolve());
  return stop3.promise;
}
